import { useEffect, useMemo, useState } from "react";
import { browseFoods, type FoodRow } from "../lib/api";
import { fa } from "../lib/useApi";

/**
 * G12 — پایگاه غذای ایرانی: مرور و فیلتر جدول واقعی.
 *
 * منبع: `soooolag/food-finder` (MIT) — ۳۰۵ غذای ایرانی، ۱۱ دسته.
 * این کامپوننت فقط نمایش است: عددها همان عددهای جدول‌اند و دسته‌ها
 * از داده استخراج می‌شوند، نه فهرست دستی که با داده ناهم‌خوان شود.
 */

export function FoodLibrary() {
  const [query, setQuery] = useState("");
  const [category, setCategory] = useState<string | null>(null);
  const [rows, setRows] = useState<FoodRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const ctrl = new AbortController();
    let alive = true;
    setLoading(true);
    setError(null);
    browseFoods(query, 100, undefined, ctrl.signal)
      .then((d) => {
        // پاسخ سرور/استاب ممکن است شکل دیگری داشته باشد؛ آرایهٔ نامعتبر نباید
        // کل صفحه را با «rows is not iterable» بترکاند.
        if (alive) setRows(Array.isArray(d) ? d : []);
      })
      .catch((e: unknown) => {
        if (e instanceof DOMException && e.name === "AbortError") return;
        if (alive) setError(e instanceof Error ? e.message : "خطای ناشناخته");
      })
      .finally(() => {
        if (alive) setLoading(false);
      });
    return () => {
      alive = false;
      ctrl.abort();
    };
  }, [query]);

  // دسته‌ها از خود داده ساخته می‌شوند — نه فهرست ثابت که با داده ناهم‌خوان شود
  const categories = useMemo(() => {
    const map = new Map<string, number>();
    for (const r of rows) map.set(r.category, (map.get(r.category) ?? 0) + 1);
    return [...map.entries()].sort((a, b) => b[1] - a[1]);
  }, [rows]);

  const visible = category === null ? rows : rows.filter((r) => r.category === category);
  const dryCount = visible.filter((r) => r.dry_or_raw).length;

  return (
    <section className="glass-card space-y-3 p-5">
      <div className="flex flex-wrap items-baseline justify-between gap-2">
        <div>
          <h3 className="font-semibold">پایگاه غذای ایرانی</h3>
          <p className="text-xs text-ink-dim">
            جدول آزاد (مجوز MIT) · اعداد برای ۱۰۰ گرم · چربی از معادلهٔ آتووتر تخمین زده شده
          </p>
        </div>
        <span className="text-[11px] text-ink-dim">
          {fa(visible.length)} از {fa(rows.length)} غذا
          {dryCount > 0 && ` · ${fa(dryCount)} با وزن خشک/خام`}
        </span>
      </div>

      <div className="flex flex-wrap gap-2">
        <input
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          placeholder="جستجو (فارسی یا انگلیسی)"
          className="focus-ring min-w-[12rem] flex-1 rounded-lg bg-surface/70 px-3 py-2 text-sm"
        />
        <button
          onClick={() => {
            setCategory(null);
            setQuery("");
          }}
          className={`px-3 py-1.5 text-xs ${category === null ? "btn-primary" : "btn-ghost"}`}
        >
          همه
        </button>
      </div>

      {loading && <p className="text-sm text-ink-dim">در حال بارگذاری…</p>}
      {error && (
        <p className="rounded-lg bg-danger/10 px-3 py-2 text-xs text-danger" role="alert">
          {error}
        </p>
      )}

      {!loading && !error && rows.length === 0 && (
        <p className="rounded-lg bg-surface/50 p-6 text-center text-sm text-ink-dim">
          {query
            ? `«${query}» در جدول غذایی نیست — عبارت دیگری را امتحان کنید.`
            : "جدول غذایی خالی است. اسکریپت واردات را اجرا کنید (scripts/import_food_catalog.py)."}
        </p>
      )}

      {categories.length > 0 && (
        <div className="flex flex-wrap gap-1.5">
          {categories.map(([cat, count]) => (
            <button
              key={cat}
              onClick={() => setCategory(category === cat ? null : cat)}
              className={`rounded-full px-2.5 py-1 text-[11px] transition-colors ${
                category === cat ? "bg-primary/25 text-white" : "bg-surface/60 text-ink-dim hover:bg-surface"
              }`}
            >
              {cat} <span className="opacity-60">{fa(count)}</span>
            </button>
          ))}
        </div>
      )}

      {visible.length > 0 && (
        <div className="max-h-[26rem] overflow-auto">
          <table className="w-full text-right text-xs">
            <thead className="sticky top-0 bg-surface/90 text-ink-dim">
              <tr>
                <th className="py-1.5 font-normal">غذا</th>
                <th className="py-1.5 font-normal">دسته</th>
                <th className="py-1.5 font-normal">کالری</th>
                <th className="py-1.5 font-normal">پروتئین</th>
                <th className="py-1.5 font-normal">کارب</th>
                <th className="py-1.5 font-normal">چربی</th>
              </tr>
            </thead>
            <tbody>
              {visible.map((f) => (
                <tr key={f.id} className="border-t border-white/5">
                  <td className="py-1.5">
                    {f.name_fa}
                    {f.dry_or_raw && (
                      <span className="mr-1 text-[10px] text-amber-300">[خشک/خام]</span>
                    )}
                  </td>
                  <td className="py-1.5 text-ink-dim">{f.category}</td>
                  <td className="py-1.5">{fa(f.kcal_per_100g)}</td>
                  <td className="py-1.5">{fa(f.protein_g_per_100g)}</td>
                  <td className="py-1.5">{fa(f.carbs_g_per_100g)}</td>
                  <td className="py-1.5">
                    {f.fat_g_per_100g === 0 ? (
                      <span className="text-ink-dim" title="چربی از دادهٔ منبع قابل استخراج نبود">
                        نامعلوم
                      </span>
                    ) : (
                      fa(f.fat_g_per_100g)
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </section>
  );
}

/**
 * دفتر پول عضو (QF-05) — موجودی، تطبیق و معکوس‌سازی با دلیل.
 *
 * چرا این پنل: API دفتر و معکوس‌سازی وجود داشت ولی هیچ مصرف‌کنندهٔ واقعی در
 * Studio نداشت؛ یعنی «قابلیت» فقط در تست بود. این‌جا همان کار از UI انجام
 * می‌شود و هر ردیف فقط با **ردیف جبرانی** و دلیل اصلاح می‌شود، نه ویرایش مبلغ.
 *
 * رفتار عمدی: هیچ درخواستی هنگام mount فرستاده نمی‌شود. کاربر اول شناسهٔ عضو
 * را می‌دهد؛ این‌طور صفحهٔ مالی با یک درخواست اضافی و بدون مقصد شلوغ نمی‌شود.
 */
import { Alert, Button, Empty, Input, InputNumber, Modal, Spin, Table, Tag } from "antd";
import { useState } from "react";
import {
  fetchMemberLedger,
  reverseLedgerEntry,
  type LedgerRow,
  type MemberLedger,
} from "../lib/api";

const KIND_LABELS: Record<LedgerRow["kind"], string> = {
  charge: "شارژ",
  pay: "پرداخت",
  refund: "بازگشت",
  reversal: "معکوس‌سازی",
};

const rial = (value: number) => `${value.toLocaleString("fa-IR")} ریال`;

export function LedgerPanel() {
  const [memberId, setMemberId] = useState<number | null>(null);
  const [ledger, setLedger] = useState<MemberLedger | null>(null);
  const [loading, setLoading] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  const [reversing, setReversing] = useState<LedgerRow | null>(null);
  const [reason, setReason] = useState("");

  async function load(id = memberId) {
    if (id === null || !Number.isFinite(id) || id < 1) {
      setError("شناسهٔ عضو باید عدد مثبت باشد");
      return;
    }
    setLoading(true);
    setError("");
    try {
      setLedger(await fetchMemberLedger(id));
    } catch (err) {
      setError(err instanceof Error ? err.message : "خواندن دفتر ناموفق بود");
    } finally {
      setLoading(false);
    }
  }

  async function submitReverse() {
    if (!reversing) return;
    if (reason.trim().length < 3) {
      setError("دلیل معکوس‌سازی اجباری است (حداقل ۳ نویسه)");
      return;
    }
    setBusy(true);
    setError("");
    try {
      await reverseLedgerEntry(reversing.id, reason.trim());
      setReversing(null);
      setReason("");
      await load();
    } catch (err) {
      setError(err instanceof Error ? err.message : "معکوس‌سازی ناموفق بود");
    } finally {
      setBusy(false);
    }
  }

  return (
    <section className="glass-card space-y-3 p-5" aria-label="دفتر پول عضو">
      <header>
        <h2 className="text-sm font-bold">دفتر پول عضو</h2>
        <p className="mt-1 text-xs text-ink-dim">
          هر حرکت کیف‌پول یک ردیف فقط-افزودنی است. اشتباه با ردیف جبرانی و دلیل اصلاح
          می‌شود؛ ردیف اصلی هرگز تغییر نمی‌کند.
        </p>
      </header>

      <div className="flex flex-wrap items-end gap-3">
        <label className="text-xs text-ink-dim">
          شناسهٔ عضو
          <InputNumber<number>
            aria-label="شناسهٔ عضو برای دفتر"
            className="mt-1 block w-36"
            min={1}
            controls={false}
            value={memberId}
            onChange={(value) => setMemberId(value)}
          />
        </label>
        <Button type="primary" onClick={() => void load()} loading={loading}>
          نمایش دفتر
        </Button>
      </div>

      {error && <Alert type="error" showIcon message={error} role="alert" />}

      {loading && !ledger ? (
        <div className="flex justify-center p-4">
          <Spin size="small" />
        </div>
      ) : ledger ? (
        <div className="space-y-3">
          <div className="grid gap-2 sm:grid-cols-3">
            <div className="rounded-xl bg-primary/10 p-3 text-center">
              <p className="text-xs text-ink-dim">موجودی کیف‌پول</p>
              <p className="text-sm font-bold">{rial(ledger.balance_rial)}</p>
            </div>
            <div className="rounded-xl bg-primary/10 p-3 text-center">
              <p className="text-xs text-ink-dim">مجموع دفتر</p>
              <p className="text-sm font-bold">{rial(ledger.reconcile.ledger_balance_rial)}</p>
            </div>
            <div className="rounded-xl bg-primary/10 p-3 text-center">
              <p className="text-xs text-ink-dim">تطبیق</p>
              <Tag color={ledger.reconcile.matches ? "green" : "red"}>
                {ledger.reconcile.matches
                  ? "منطبق"
                  : `اختلاف ${rial(ledger.reconcile.difference_rial)}`}
              </Tag>
            </div>
          </div>

          {ledger.entries.length === 0 ? (
            <Empty description="رویدادی برای این عضو ثبت نشده است" />
          ) : (
            <Table<LedgerRow>
              size="small"
              rowKey="id"
              pagination={false}
              dataSource={ledger.entries}
              columns={[
                { title: "شناسه", dataIndex: "id", key: "id" },
                {
                  title: "نوع",
                  key: "kind",
                  render: (_, row) => <Tag>{KIND_LABELS[row.kind] ?? row.kind}</Tag>,
                },
                {
                  title: "مبلغ",
                  key: "amount_rial",
                  render: (_, row) => rial(row.amount_rial),
                },
                {
                  title: "وضعیت",
                  key: "status",
                  render: (_, row) =>
                    row.reversed_by_entry_id ? (
                      <Tag color="orange">معکوس‌شده</Tag>
                    ) : row.reverses_entry_id ? (
                      <Tag color="purple">جبرانی</Tag>
                    ) : (
                      <Tag color="green">فعال</Tag>
                    ),
                },
                {
                  title: "",
                  key: "actions",
                  render: (_, row) => (
                    <Button
                      size="small"
                      disabled={row.reversed_by_entry_id !== null || row.kind === "reversal"}
                      onClick={() => {
                        setReversing(row);
                        setReason("");
                      }}
                    >
                      معکوس‌سازی
                    </Button>
                  ),
                },
              ]}
            />
          )}
        </div>
      ) : null}

      <Modal
        title="معکوس‌سازی ردیف دفتر"
        open={reversing !== null}
        okText="ثبت معکوس"
        cancelText="انصراف"
        confirmLoading={busy}
        onOk={() => void submitReverse()}
        onCancel={() => {
          setReversing(null);
          setReason("");
        }}
      >
        <p className="text-xs text-ink-dim">
          ردیف جبرانی با علامت مخالف ساخته می‌شود و در ممیزی با نام شما ثبت است. دلیل
          اجباری است.
        </p>
        <Input
          aria-label="دلیل معکوس‌سازی"
          className="mt-3"
          placeholder="دلیل (اجباری)"
          value={reason}
          onChange={(e) => setReason(e.target.value)}
        />
      </Modal>
    </section>
  );
}

import { useRef, useState } from "react";
import {
  createPayment,
  verifyPayment,
  failPayment,
  fetchReceipt,
  listPayments,
  refundPayment,
  type PaymentRow,
  type Receipt,
} from "../lib/api";
import { fa } from "../lib/useApi";
import { Input, Select } from "antd";

/**
 * Q6 — درگاه پرداخت (پذیرش).
 *
 * پیش از این `modules/payments/gateway.py` (Mock + زرین‌پال + امضای HMAC)
 * کامل نوشته شده بود ولی **هیچ مصرف‌کننده‌ای نداشت**: هیچ صفحه‌ای نمی‌توانست
 * تراکنش را در درگاه آغاز کند، پس پرداخت همیشه pending می‌ماند.
 *
 * جریان واقعی: ساخت تراکنش → start (authority از درگاه) → هدایت کاربر →
 * callback با امضای مبلغ. دکمهٔ «پرداخت شد» بدون authority کار نمی‌کند.
 *
 * قاعدهٔ بازنمایی: مبلغ هرگز از پاسخ callback گرفته نمی‌شود؛ مبلغ نمایش‌داده‌شده
 * همان مبلغ ثبت‌شده در DB است.
 */

const fmt = (n: number) => n.toLocaleString("fa-IR");

export function PaymentPanel() {
  const [memberId, setMemberId] = useState("");
  const [lookupId, setLookupId] = useState("");
  const [amount, setAmount] = useState("500000");
  // فاز ۳: فقط پرداخت حضوری؛ هیچ گزینهٔ درگاه اینترنتی نمی‌ماند.
  const [method, setMethod] = useState<"cash" | "card">("cash");
  const [coupon, setCoupon] = useState("");
  const [tx, setTx] = useState<PaymentRow | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [receipt, setReceipt] = useState<Receipt | null>(null);
  const [busy, setBusy] = useState(false);
  const busyRef = useRef(false);

  async function call<T>(fn: () => Promise<T>): Promise<T | null> {
    // Guard synchronously too: two clicks can arrive before React renders `busy`.
    if (busyRef.current) return null;
    busyRef.current = true;
    setBusy(true);
    setError(null);
    try {
      return await fn();
    } catch (e) {
      setError(e instanceof Error ? e.message : "خطای ناشناخته");
      return null;
    } finally {
      busyRef.current = false;
      setBusy(false);
    }
  }

  const clearSelection = () => {
    setTx(null);
    setReceipt(null);
  };

  const create = () =>
    call(async () => {
      const mid = Number(memberId);
      const amt = Number(amount);
      if (!Number.isInteger(mid) || mid <= 0) throw new Error("شناسهٔ عضو باید عدد صحیح مثبت باشد");
      if (!Number.isInteger(amt) || amt < 1000) throw new Error("مبلغ حداقل ۱۰۰۰ ریال است");
      const code = coupon.trim();
      const created = await createPayment({
        member_id: mid,
        amount_rial: amt,
        method,
        ...(code ? { coupon_code: code } : {}),
      });
      setTx(created);
    });

  const confirmManual = () =>
    call(async () => {
      if (!tx) throw new Error("اول تراکنش را بسازید");
      // پذیرش نقدی/کارت‌خوان: مرجع پیگیری دستی ثبت می‌شود، نه ادعای درگاه.
      const paid = await verifyPayment(tx.id, `manual-${tx.id}`);
      setTx(paid);
    });

  const markFailed = () =>
    call(async () => {
      if (!tx) throw new Error("تراکنشی نیست");
      const failed = await failPayment(tx.id);
      setTx(failed);
    });

  const loadReceipt = () =>
    call(async () => {
      if (!tx) throw new Error("تراکنشی نیست");
      setReceipt(await fetchReceipt(tx.id));
    });

  const lookup = () =>
    call(async () => {
      // An unsuccessful lookup must never leave a previously selected refund target.
      clearSelection();
      const id = Number(lookupId);
      if (!Number.isSafeInteger(id) || id <= 0) throw new Error("شناسهٔ پرداخت نامعتبر است");
      const payment = (await listPayments()).find((p) => p.id === id);
      if (!payment) throw new Error("پرداخت یافت نشد");
      setTx(payment);
      setReceipt(null);
    });

  const refund = () =>
    call(async () => {
      if (!tx) throw new Error("تراکنشی نیست");
      if (!window.confirm(`بازگشت ${fmt(tx.amount_rial)} ریال برای پرداخت #${tx.id}؟`)) return;
      const updated = await refundPayment(tx.id);
      setTx(updated);
      setReceipt(null);
    });

  const reset = () => {
    clearSelection();
    setError(null);
  };

  return (
    <section className="glass-card space-y-4 p-5">
      <div>
        <h2 className="text-sm font-bold">پرداخت حضوری</h2>
        <p className="text-xs text-ink-dim">
          پرداخت اینترنتی حذف شده است؛ نقدی یا کارت‌خوان در پذیرش ثبت و تأیید می‌شود.
        </p>
      </div>

      <div className="flex flex-wrap items-end gap-2 text-xs">
        <label className="text-ink-dim">
          شناسهٔ عضو
          <input
            value={memberId}
            onChange={(e) => setMemberId(e.target.value)}
            inputMode="numeric"
            className="focus-ring mt-1 block w-28 rounded-lg bg-surface/70 px-3 py-2 text-sm"
          />
        </label>
        <label className="text-ink-dim">
          مبلغ (ریال)
          <input
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
            inputMode="numeric"
            className="focus-ring mt-1 block w-36 rounded-lg bg-surface/70 px-3 py-2 text-sm"
          />
        </label>
        <label className="text-ink-dim">
          کد تخفیف (اختیاری)
          <Input
            value={coupon}
            onChange={(e) => setCoupon(e.target.value)}
            className="mt-1 block w-36"
          />
        </label>
        <div className="text-ink-dim">
          <span>روش</span>
          <Select
            aria-label="روش پرداخت"
            className="mt-1 block w-44"
            options={[
              { value: "cash", label: "نقدی (پذیرش)" },
              { value: "card", label: "کارت‌خوان" },
            ]}
            value={method}
            onChange={(value) => setMethod(value as typeof method)}
          />
        </div>
        <button
          onClick={() => void create()}
          disabled={busy}
          className="btn-primary px-4 py-2 text-xs disabled:opacity-50"
        >
          {busy ? "…" : "ساخت تراکنش"}
        </button>
      </div>

      <div className="flex items-end gap-2 text-xs">
        <label>شناسهٔ پرداخت موجود
          <input value={lookupId} onChange={(e) => {
            setLookupId(e.target.value);
            clearSelection();
            setError(null);
          }} inputMode="numeric" disabled={busy}
            className="focus-ring mt-1 block w-28 rounded-lg bg-surface/70 px-3 py-2 text-sm" />
        </label>
        <button onClick={() => void lookup()} disabled={busy} className="btn-primary px-4 py-2">
          بارگذاری پرداخت
        </button>
      </div>

      {error && (
        <p role="alert" className="text-xs text-rose-400">
          {error}
        </p>
      )}

      {tx && (
        <div className="space-y-2 rounded-lg bg-surface/60 p-3 text-xs">
          <p>
            تراکنش #{tx.id} — مبلغ <b>{fmt(tx.amount_rial)}</b> ریال · وضعیت:{" "}
            <b className={tx.status === "paid" ? "text-emerald-400" : "text-ink"}>{tx.status}</b>
          </p>
          {tx.reference_id && <p className="text-ink-dim">کد پیگیری: {tx.reference_id}</p>}

          {tx.status === "pending" && (
            <button
              onClick={() => void confirmManual()}
              disabled={busy}
              className="rounded-lg bg-emerald-600 px-4 py-2 text-xs text-white disabled:opacity-50"
            >
              تأیید دریافت نقدی/کارت‌خوان
            </button>
          )}

          {tx.status === "pending" && (
            <button
              onClick={() => void markFailed()}
              disabled={busy}
              className="rounded-lg border border-rose-500/40 px-3 py-1.5 text-rose-300 disabled:opacity-50"
            >
              ثبت شکست تراکنش
            </button>
          )}

          {tx.status === "paid" && tx.gateway_authority && (
            <button onClick={() => void refund()} disabled={busy}
              className="rounded-lg border border-rose-500/40 px-3 py-1.5 text-rose-300 disabled:opacity-50">
              بازگشت وجه
            </button>
          )}

          {(tx.status === "paid" || tx.status === "refunded") && (
            <button
              onClick={() => void loadReceipt()}
              disabled={busy}
              className="rounded-lg border border-emerald-500/40 px-3 py-1.5 text-emerald-300 disabled:opacity-50"
            >
              نمایش رسید
            </button>
          )}

          {receipt && (
            <div className="mt-2 rounded-lg border border-emerald-500/30 p-3 text-[11px] leading-6">
              <p className="font-bold">{receipt.status === "refunded" ? "رسید بازگشت وجه" : "رسید پرداخت"} #{receipt.payment_id}</p>
              <p>مبلغ: {fmt(receipt.amount_rial)} ریال</p>
              <p>کد پیگیری پرداخت: {receipt.reference_id}</p>
              {receipt.status === "refunded" && <p>مرجع بازگشت: {receipt.refund_reference || "ثبت نشده توسط درگاه"}</p>}
              {receipt.paid_at && <p>زمان: {new Date(receipt.paid_at).toLocaleString("fa-IR")}</p>}
            </div>
          )}

          <button onClick={reset} disabled={busy} className="text-ink-dim underline">
            پاک کردن
          </button>
        </div>
      )}
    </section>
  );
}

