/**
 * hook مشترک دریافت داده از API واقعی (M45-c1).
 *
 * سه حالت صریح، بدون پنهان‌کاری:
 * loading | error (با پیام واقعی) | data
 * و یک حالت چهارم: `needsSession` — نشست پس از refresh هم ۴۰۱ گرفته است و
 * کاربر باید دوباره با OTP وارد شود؛ ۴۰۳ در error می‌ماند چون مسئله نقش است.
 */

import { useCallback, useEffect, useState } from "react";
import { AuthError } from "./api";

export interface ApiState<T> {
  data: T | null;
  loading: boolean;
  error: string | null;
  needsSession: boolean;
  reload: () => void;
}

export function useApi<T>(
  fetcher: (signal?: AbortSignal) => Promise<T>,
  deps: unknown[] = [],
): ApiState<T> {
  const [data, setData] = useState<T | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [needsSession, setNeedsSession] = useState(false);
  const [nonce, setNonce] = useState(0);

  const reload = useCallback(() => setNonce((n) => n + 1), []);

  useEffect(() => {
    const ctrl = new AbortController();
    let alive = true;
    setLoading(true);
    setError(null);
    fetcher(ctrl.signal)
      .then((d) => {
        if (!alive) return;
        setData(d);
        setNeedsSession(false);
      })
      .catch((e: unknown) => {
        if (!alive) return;
        if (e instanceof DOMException && e.name === "AbortError") return;
        if (e instanceof AuthError) {
          setNeedsSession(true);
          setData(null);
        }
        setError(e instanceof Error ? e.message : "خطای ناشناخته");
      })
      .finally(() => {
        if (alive) setLoading(false);
      });
    return () => {
      alive = false;
      ctrl.abort();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [...deps, nonce]);

  return { data, loading, error, needsSession, reload };
}

/**
 * فرمت اعداد فارسی — یک‌جا، تا هر صفحه جداگانه تکرارش نکند.
 *
 * `null`/`undefined` به «—» تبدیل می‌شود، نه به کرش و نه به صفر. دلیل: در
 * پاسخ ناقص یا هنوز نیامده، «۰ ریال» یک عدد جعلی است؛ «—» صادقانه می‌گوید
 * داده نداریم. این باگ در تست a11y دیده شد: صفحهٔ مالی قبل از رسیدن KPI
 * با `n.toLocaleString` می‌ترکید (Unhandled error در Vitest).
 */
export const fa = (n: number | null | undefined): string =>
  typeof n === "number" && Number.isFinite(n) ? n.toLocaleString("fa-IR") : "—";

import { useEffect, useState } from "react";
import { motion } from "framer-motion";
import { useMotionPreset } from "../lib/motion";
import { fetchChurnRisk, fetchLeaderboards, type ChurnRow, type Leaderboards } from "../lib/adminApi";

const sections: { key: keyof Leaderboards; title: string; hint: string }[] = [
  { key: "top_athletes", title: "بهترین ورزشکارها", hint: "میانگین نمرهٔ ۱۴ محور آخرین ارزیابی" },
  { key: "top_spenders", title: "بیشترین هزینه", hint: "جمع پرداخت‌های قطعی (paid)" },
  { key: "most_visits", title: "بیشترین مراجعه", hint: "چک‌این‌های موفق بازه" },
  { key: "most_time", title: "بیشترین تایم باشگاه", hint: "مجموع دقیقهٔ جلسات بسته‌شده" },
];

/** تحلیل‌های مدیریتی (M42-c3) — لیدربوردها از API واقعی، هر رتبه با روش محاسبه. */
export function Analytics() {
  const motionPreset = useMotionPreset();
  const [data, setData] = useState<Leaderboards | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [churn, setChurn] = useState<ChurnRow[]>([]);

  const load = () => {
    setError(null);
    fetchLeaderboards()
      .then((d) => {
        setData(d);
        return fetchChurnRisk();
      })
      .then(setChurn)
      .catch((e) => {
        setError(e instanceof Error ? e.message : "خطای ناشناخته");
      });
  };

  useEffect(load, []);

  return (
    <div className="space-y-5">
      <div className="glass-card flex flex-wrap items-center justify-between gap-3 p-5">
        <div>
          <h2 className="text-lg font-bold">تحلیل‌های مدیریتی</h2>
          <p className="mt-1 text-xs text-ink-dim">
            لیدربوردها از دادهٔ واقعی باشگاه — هر رتبه با روش محاسبه؛ بدون داده = بدون رتبه (نامعلوم ≠ صفر)
          </p>
        </div>
        {data && (
          <span className="rounded-full bg-primary/10 px-3 py-1 text-[11px] text-primary-light">
            {data.rule_version} · بازه {data.window_days.toLocaleString("fa-IR")} روز
          </span>
        )}
      </div>

      {error && <div role="alert" className="glass-card p-4 text-sm text-red-400">{error}</div>}

      <motion.div {...motionPreset.rise} className="glass-card p-5">
        <h3 className="text-sm font-bold">در خطر ریزش (churn)</h3>
        <p className="mt-0.5 text-[11px] text-ink-dim">
          قواعد شفاف: بی‌فعالیتی/انقضای نزدیک/بدهی/افت مراجعه با دلیل — بدون داده = نامعلوم (نه صفر)
        </p>
        <div className="mt-3 space-y-2">
          {churn.length === 0 && <p className="text-xs text-ink-dim">داده‌ای نیست</p>}
          {churn.slice(0, 8).map((row) => (
            <div key={row.member_id} className="flex items-start gap-3 rounded-xl bg-surface/60 px-3 py-2">
              <span
                className={`mt-0.5 rounded-full px-2 py-0.5 text-[10px] ${
                  row.band === "high" ? "bg-red-500/15 text-red-400"
                  : row.band === "medium" ? "bg-amber-500/15 text-amber-400"
                  : row.band === "unknown" ? "bg-surface text-ink-dim"
                  : "bg-green-500/15 text-green-400"
                }`}
              >
                {row.band === "high" ? "ریسک بالا" : row.band === "medium" ? "ریسک متوسط" : row.band === "unknown" ? "نامعلوم" : "ریسک پایین"}
              </span>
              <div className="flex-1">
                <p className="text-sm">{row.full_name || `عضو ${row.member_id}`}</p>
                <p className="text-[11px] text-ink-dim">{row.reason}</p>
              </div>
              <span className="text-xs text-ink-dim">{row.risk_score ?? "—"}</span>
            </div>
          ))}
        </div>
      </motion.div>

      <div className="grid grid-cols-1 gap-5 xl:grid-cols-2">
        {sections.map((sec) => (
          <motion.div key={sec.key} {...motionPreset.rise} className="glass-card p-5">
            <h3 className="text-sm font-bold">{sec.title}</h3>
            <p className="mt-0.5 text-[11px] text-ink-dim">{sec.hint}</p>
            <div className="mt-3 space-y-2">
              {(!data || (data[sec.key] as unknown[]).length === 0) && (
                <p className="text-xs text-ink-dim">داده‌ای ثبت نشده — رتبه‌ای نمایش داده نمی‌شود</p>
              )}
              {data &&
                (data[sec.key] as Record<string, unknown>[]).map((row, i) => (
                  <div key={String(row.member_id)} className="flex items-center gap-3 rounded-xl bg-surface/60 px-3 py-2">
                    <span className="w-6 text-center text-sm font-bold text-primary-light">
                      {(i + 1).toLocaleString("fa-IR")}
                    </span>
                    <span className="flex-1 truncate text-sm">{String(row.full_name || row.member_id)}</span>
                    <span className="text-xs text-ink-dim">
                      {sec.key === "top_athletes" && `میانگین ${Number(row.avg_axis_score).toLocaleString("fa-IR")}`}
                      {sec.key === "top_spenders" &&
                        `${Number(row.total_paid_rial).toLocaleString("fa-IR")} ریال`}
                      {sec.key === "most_visits" &&
                        `${Number(row.visits).toLocaleString("fa-IR")} مراجعه`}
                      {sec.key === "most_time" &&
                        `${Number(row.total_minutes).toLocaleString("fa-IR")} دقیقه`}
                    </span>
                  </div>
                ))}
            </div>
          </motion.div>
        ))}
      </div>
    </div>
  );
}

