import { useCallback, useEffect, useRef, useState } from "react";
import {
  fetchConversations,
  fetchMessages,
  markConversationRead,
  openConversation,
  sendMessage,
  type ChatConversation,
  type ChatMessage,
} from "../lib/api";
import { useAppStore } from "../stores/appStore";
import { fa } from "../lib/useApi";

/**
 * G8 — چت مربی–شاگرد.
 *
 * تصمیم‌های UI:
 *   • خوانده‌نشده از سرور می‌آید، نه از یک شمارندهٔ محلی که با refresh گم شود
 *   • بعد از خواندن پیام‌ها، `read` صدا زده می‌شود و شمارنده واقعاً صفر می‌شود
 *   • ارسال ناموفق ⇒ متن در کادر می‌ماند تا کاربر داده‌اش را از دست ندهد
 *   • پیام خالی هرگز فرستاده نمی‌شود (هم UI هم سرور)
 */

function timeFa(iso: string | null): string {
  if (!iso) return "";
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return "";
  return d.toLocaleTimeString("fa-IR", { hour: "2-digit", minute: "2-digit" });
}

export function Chat() {
  const selectedMemberId = useAppStore((s) => s.selectedMemberId);
  const [conversations, setConversations] = useState<ChatConversation[]>([]);
  const [activeId, setActiveId] = useState<number | null>(null);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [unread, setUnread] = useState(0);
  const [draft, setDraft] = useState("");
  const [subject, setSubject] = useState("");
  const [loading, setLoading] = useState(true);
  const [sending, setSending] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);
  const bottomRef = useRef<HTMLDivElement | null>(null);

  const loadConversations = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const rows = await fetchConversations(
        selectedMemberId === null ? undefined : selectedMemberId,
      );
      setConversations(rows);
      setActiveId((cur) => cur ?? rows[0]?.id ?? null);
    } catch (e) {
      setError((e as Error).message);
    } finally {
      setLoading(false);
    }
  }, [selectedMemberId]);

  useEffect(() => {
    void loadConversations();
  }, [loadConversations]);

  const loadMessages = useCallback(async (id: number) => {
    try {
      const data = await fetchMessages(id);
      setMessages(data.messages);
      setUnread(data.unread_count);
    } catch (e) {
      setError((e as Error).message);
    }
  }, []);

  useEffect(() => {
    if (activeId === null) {
      setMessages([]);
      setUnread(0);
      return;
    }
    void loadMessages(activeId);
  }, [activeId, loadMessages]);

  useEffect(() => {
    // optional-call: محیط‌های بدون scrollIntoView (jsdom، مرورگرهای قدیمی)
    // نباید کل صفحهٔ چت را با استثنا از کار بیندازند.
    bottomRef.current?.scrollIntoView?.({ block: "end" });
  }, [messages]);

  async function startConversation() {
    if (selectedMemberId === null) {
      setError("برای شروع گفتگو، اول یک عضو را از صفحهٔ «اعضا» انتخاب کنید.");
      return;
    }
    setError(null);
    try {
      const conv = await openConversation(selectedMemberId, subject.trim());
      setSubject("");
      await loadConversations();
      setActiveId(conv.id);
      setNotice("گفتگوی جدید ساخته شد.");
    } catch (e) {
      setError((e as Error).message);
    }
  }

  async function submit() {
    const text = draft.trim();
    if (!text || activeId === null) return;
    setSending(true);
    setError(null);
    try {
      const msg = await sendMessage(activeId, text);
      setMessages((prev) => [...prev, msg]);
      setDraft("");
      setNotice(null);
      void loadConversations();
    } catch (e) {
      // متن پاک نمی‌شود — کاربر نباید چیزی را از دست بدهد
      setError((e as Error).message);
    } finally {
      setSending(false);
    }
  }

  async function markRead() {
    if (activeId === null || unread === 0) return;
    try {
      const res = await markConversationRead(activeId);
      setUnread(0);
      setNotice(`${fa(res.marked_read)} پیام خوانده‌شده علامت خورد.`);
      await loadMessages(activeId);
    } catch (e) {
      setError((e as Error).message);
    }
  }

  const active = conversations.find((c) => c.id === activeId) ?? null;

  return (
    <div className="grid gap-4 lg:grid-cols-[18rem_1fr]">
      <aside className="glass-card flex max-h-[36rem] flex-col gap-3 p-4">
        <div className="flex items-center justify-between">
          <h3 className="font-semibold">گفتگوها</h3>
          <button onClick={() => void loadConversations()} className="btn-ghost px-2 py-1 text-[11px]">
            بازخوانی
          </button>
        </div>

        <div className="flex gap-1">
          <input
            value={subject}
            onChange={(e) => setSubject(e.target.value)}
            placeholder="موضوع گفتگوی جدید"
            className="focus-ring min-w-0 flex-1 rounded-lg bg-surface/70 px-2 py-1.5 text-xs"
          />
          <button onClick={() => void startConversation()} className="btn-primary px-2 py-1.5 text-[11px]">
            شروع
          </button>
        </div>

        {loading && <p className="text-xs text-ink-dim">در حال بارگذاری…</p>}
        {!loading && conversations.length === 0 && (
          <p className="rounded-lg bg-surface/50 p-3 text-xs text-ink-dim">
            هیچ گفتگویی نیست. گفتگو با موضوع مشخص شروع می‌شود — گفتگوی خالی ساخته نمی‌شود.
          </p>
        )}

        <div className="flex-1 space-y-1 overflow-auto">
          {conversations.map((c) => (
            <button
              key={c.id}
              onClick={() => {
                setActiveId(c.id);
                setNotice(null);
              }}
              className={`w-full rounded-lg px-3 py-2 text-right text-xs transition-colors ${
                c.id === activeId ? "bg-primary/20 text-white" : "bg-surface/50 hover:bg-surface/80"
              }`}
            >
              <span className="block truncate">{c.subject || `گفتگو #${c.id}`}</span>
              <span className="text-[10px] text-ink-dim">
                {c.last_message_at
                  ? `آخرین پیام ${timeFa(c.last_message_at)}`
                  : "بدون پیام"}
                {c.status === "closed" && " · بسته"}
              </span>
            </button>
          ))}
        </div>
      </aside>

      <section className="glass-card flex max-h-[36rem] flex-col gap-3 p-4">
        {error && (
          <p className="rounded-lg bg-danger/10 px-3 py-2 text-xs text-danger" role="alert">
            {error}
          </p>
        )}
        {notice && <p className="text-[11px] text-emerald-300">{notice}</p>}

        {active === null ? (
          <p className="m-auto text-sm text-ink-dim">
            یک گفتگو را از فهرست انتخاب کنید یا گفتگوی جدیدی شروع کنید.
          </p>
        ) : (
          <>
            <div className="flex items-center justify-between border-b border-white/10 pb-2">
              <div>
                <p className="text-sm font-medium">{active.subject || `گفتگو #${active.id}`}</p>
                <p className="text-[10px] text-ink-dim">
                  عضو #{fa(active.member_id)} · مربی #{fa(active.coach_id)}
                </p>
              </div>
              {unread > 0 && (
                <button onClick={() => void markRead()} className="btn-ghost px-2 py-1 text-[11px]">
                  {fa(unread)} خوانده‌نشده — علامت بزن
                </button>
              )}
            </div>

            <div className="flex-1 space-y-2 overflow-auto">
              {messages.length === 0 && (
                <p className="p-4 text-center text-xs text-ink-dim">
                  هنوز پیامی نیست. اولین پیام را بنویسید.
                </p>
              )}
              {messages.map((m) => (
                <div
                  key={m.id}
                  className={`max-w-[80%] rounded-xl px-3 py-2 text-xs ${
                    m.sender_role === "coach"
                      ? "ml-auto bg-primary/20"
                      : "mr-auto bg-surface/70"
                  }`}
                >
                  <p className="whitespace-pre-wrap">{m.body}</p>
                  <p className="mt-1 text-[10px] text-ink-dim">
                    {m.sender_role === "coach" ? "مربی" : "عضو"} · {timeFa(m.created_at)}
                    {m.read_at === null && " · خوانده نشده"}
                  </p>
                </div>
              ))}
              <div ref={bottomRef} />
            </div>

            <div className="flex gap-2 border-t border-white/10 pt-2">
              <textarea
                value={draft}
                onChange={(e) => setDraft(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === "Enter" && !e.shiftKey) {
                    e.preventDefault();
                    void submit();
                  }
                }}
                rows={2}
                placeholder="پیام… (Enter برای ارسال، Shift+Enter خط جدید)"
                className="focus-ring min-w-0 flex-1 resize-none rounded-lg bg-surface/70 px-3 py-2 text-xs"
              />
              <button
                onClick={() => void submit()}
                disabled={sending || draft.trim().length === 0}
                className="btn-primary self-end px-4 py-2 text-xs disabled:opacity-50"
              >
                {sending ? "…" : "ارسال"}
              </button>
            </div>
          </>
        )}
      </section>
    </div>
  );
}

import { Alert, Button, Empty, Input, InputNumber, Modal, Select, Spin, Table, Tag, Upload } from "antd";
import { useCallback, useEffect, useState } from "react";
import {
  EXPENSE_CATEGORIES,
  createExpense,
  deleteExpense,
  fetchExpenseReceiptBlob,
  fetchExpenses,
  updateExpense,
  type ExpenseCategory,
  type ExpensePeriod,
  type ExpenseRow,
  uploadExpenseReceipt,
} from "../lib/api";
import { JalaliDateField, isoFromLocal } from "../components/ui/JalaliDateField";
import { canSeePage, parseRole } from "../lib/roleNav";
import { fa } from "../lib/useApi";

/**
 * هزینه‌های باشگاه (QF-06) — اجاره، حقوق، تجهیزات و بقیهٔ پول‌های خارج‌شده.
 *
 * چرا این صفحه لازم بود: پیش از این فقط **درآمد** دیده می‌شد، پس هر عدد
 * «سود» در بهترین حالت حدس بود. حالا هزینه با دسته و تاریخ ثبت می‌شود و جمع
 * همان دوره از سرور می‌آید.
 *
 * قواعدی که UI رعایت می‌کند و سرور هم جداگانه تحمیل می‌کند:
 * - هر اصلاح و حذف **دلیل** می‌خواهد؛ بدون دلیل درخواست فرستاده نمی‌شود.
 * - حذف نرم است؛ ردیف از جمع بیرون می‌رود ولی تاریخچه‌اش می‌ماند.
 * - مجوز نوشتن `finance.write` و خواندن `finance.read`؛ ۴۰۳ سرور نمایش داده
 *   می‌شود و UI ادعای موفقیت نمی‌کند.
 * - کنترل‌ها از کتابخانهٔ antd/تقویم جلالی می‌آیند (Q11)، نه input دست‌ساز.
 */

const labelOf = (key: string): string =>
  EXPENSE_CATEGORIES.find((c) => c.key === key)?.label ?? key;

const isoDay = (offsetDays = 0): string => {
  const d = new Date();
  d.setDate(d.getDate() + offsetDays);
  return isoFromLocal(d);
};

export function Expenses() {
  const role = parseRole();
  const [from, setFrom] = useState(isoDay(-30));
  const [to, setTo] = useState(isoDay(0));
  const [period, setPeriod] = useState<ExpensePeriod | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);

  const [amount, setAmount] = useState<number | null>(null);
  const [category, setCategory] = useState<ExpenseCategory>("rent");
  const [spentOn, setSpentOn] = useState(isoDay(0));
  const [payee, setPayee] = useState("");
  const [note, setNote] = useState("");

  // اصلاح مبلغ: مودال کتابخانه‌ای با دلیل اجباری
  const [editing, setEditing] = useState<ExpenseRow | null>(null);
  const [editAmount, setEditAmount] = useState<number | null>(null);
  const [editReason, setEditReason] = useState("");
  // حذف نرم: مودال با دلیل اجباری
  const [removing, setRemoving] = useState<ExpenseRow | null>(null);
  const [removeReason, setRemoveReason] = useState("");

  const load = useCallback(
    (start = from, end = to) => {
      setLoading(true);
      setError("");
      return fetchExpenses(start, end)
        .then((data) => setPeriod(data))
        .catch((err: unknown) =>
          setError(err instanceof Error ? err.message : "خطا در خواندن هزینه‌ها"),
        )
        .finally(() => setLoading(false));
    },
    [from, to],
  );

  useEffect(() => {
    void load(from, to);
    // یک‌بار در باز شدن صفحه؛ تغییر بازه با دکمهٔ «نمایش دوره» انجام می‌شود.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  async function uploadReceipt(id: number, file: File) {
    setError("");
    try {
      await uploadExpenseReceipt(id, file);
    } catch (e) {
      setError(e instanceof Error ? e.message : "خطای ناشناخته");
    }
  }

  async function openReceipt(id: number) {
    setError("");
    try {
      const blob = await fetchExpenseReceiptBlob(id);
      const url = URL.createObjectURL(blob);
      window.open(url, "_blank", "noopener");
      // فایل خصوصی است؛ آدرس موقت پس از باز شدن پاک می‌شود.
      setTimeout(() => URL.revokeObjectURL(url), 60_000);
    } catch (e) {
      setError(e instanceof Error ? e.message : "خطای ناشناخته");
    }
  }

  async function submit() {
    if (amount === null || !Number.isFinite(amount) || amount < 1000) {
      setError("مبلغ هزینه باید عددی و حداقل ۱٬۰۰۰ ریال باشد");
      return;
    }
    setBusy(true);
    setError("");
    try {
      await createExpense({
        amount_rial: amount,
        category,
        spent_on: spentOn,
        payee: payee.trim(),
        note: note.trim(),
      });
      setAmount(null);
      setNote("");
      setPayee("");
      await load();
    } catch (err) {
      setError(err instanceof Error ? err.message : "ثبت هزینه ناموفق بود");
    } finally {
      setBusy(false);
    }
  }

  async function submitEdit() {
    if (!editing) return;
    if (editAmount === null || editAmount < 1000) {
      setError("مبلغ اصلاح‌شده باید حداقل ۱٬۰۰۰ ریال باشد");
      return;
    }
    if (editReason.trim().length < 3) {
      setError("دلیل اصلاح اجباری است (حداقل ۳ نویسه)");
      return;
    }
    if (editAmount === editing.amount_rial) {
      setError("مبلغ تغییری نکرده است");
      return;
    }
    setBusy(true);
    setError("");
    try {
      await updateExpense(editing.id, {
        amount_rial: editAmount,
        reason: editReason.trim(),
      });
      setEditing(null);
      setEditReason("");
      await load();
    } catch (err) {
      setError(err instanceof Error ? err.message : "اصلاح هزینه ناموفق بود");
    } finally {
      setBusy(false);
    }
  }

  async function submitRemove() {
    if (!removing) return;
    if (removeReason.trim().length < 3) {
      setError("برای حذف، دلیل حداقل ۳ نویسه لازم است");
      return;
    }
    setBusy(true);
    setError("");
    try {
      await deleteExpense(removing.id, removeReason.trim());
      setRemoving(null);
      setRemoveReason("");
      await load();
    } catch (err) {
      setError(err instanceof Error ? err.message : "حذف هزینه ناموفق بود");
    } finally {
      setBusy(false);
    }
  }

  if (role && !canSeePage("expenses", role)) {
    return (
      <div className="glass-card p-5 text-sm text-ink-dim" role="alert">
        هزینه‌ها برای نقش شما مجاز نیست. سرور هم این را رد می‌کند (۴۰۳) — این پیام فقط
        توضیح می‌دهد چرا صفحه خالی است.
      </div>
    );
  }

  return (
    <section className="space-y-4" aria-label="هزینه‌های باشگاه">
      <div className="glass-card space-y-4 p-5">
        <h2 className="text-sm font-bold">هزینه‌های باشگاه</h2>
        <div className="flex flex-wrap items-end gap-3">
          <JalaliDateField label="از تاریخ" value={from} onChange={setFrom} />
          <JalaliDateField label="تا تاریخ" value={to} onChange={setTo} />
          <Button type="primary" onClick={() => void load()} loading={loading}>
            نمایش دوره
          </Button>
        </div>

        {loading && !period ? (
          <div className="flex justify-center p-4">
            <Spin size="small" />
          </div>
        ) : period ? (
          <div className="space-y-3">
            <p className="text-sm">
              جمع هزینهٔ دوره: <b className="text-primary-light">{fa(period.total_rial)}</b> ریال —{" "}
              {fa(period.count)} ردیف
            </p>
            {period.by_category.length > 0 ? (
              <div className="grid gap-2 sm:grid-cols-3">
                {period.by_category.map((row) => (
                  <div key={row.category} className="rounded-xl bg-primary/10 p-3 text-center">
                    <p className="text-xs text-ink-dim">{row.label}</p>
                    <p className="text-sm font-bold">{fa(row.total_rial)}</p>
                    <p className="text-xs text-ink-dim">{fa(row.count)} مورد</p>
                  </div>
                ))}
              </div>
            ) : (
              <p className="text-xs text-ink-dim">
                در این دوره هزینه‌ای ثبت نشده است — «صفر» یعنی ثبت نشده، نه اینکه رایگان بوده.
              </p>
            )}
          </div>
        ) : null}
      </div>

      <div className="glass-card space-y-3 p-5">
        <h2 className="text-sm font-bold">ثبت هزینهٔ تازه</h2>
        <div className="flex flex-wrap items-end gap-3">
          <label className="text-xs text-ink-dim">
            مبلغ (ریال)
            <InputNumber<number>
              aria-label="مبلغ هزینه"
              className="mt-1 block w-40"
              min={1000}
              step={1000}
              controls={false}
              value={amount}
              onChange={(value) => setAmount(value)}
            />
          </label>
          <label className="text-xs text-ink-dim">
            دسته
            <Select<ExpenseCategory>
              aria-label="دستهٔ هزینه"
              className="mt-1 block w-40"
              value={category}
              onChange={(value) => setCategory(value)}
              options={EXPENSE_CATEGORIES.map((c) => ({ value: c.key, label: c.label }))}
            />
          </label>
          <JalaliDateField label="تاریخ هزینه" value={spentOn} onChange={setSpentOn} />
          <label className="text-xs text-ink-dim">
            طرف‌حساب (اختیاری)
            <Input
              aria-label="طرف‌حساب"
              className="mt-1 block w-44"
              value={payee}
              onChange={(e) => setPayee(e.target.value)}
            />
          </label>
          <label className="text-xs text-ink-dim">
            توضیح (اختیاری)
            <Input
              aria-label="توضیح هزینه"
              className="mt-1 block w-56"
              value={note}
              onChange={(e) => setNote(e.target.value)}
            />
          </label>
          <Button type="primary" onClick={() => void submit()} loading={busy}>
            ثبت هزینه
          </Button>
        </div>
      </div>

      <div className="glass-card space-y-3 p-5">
        <h2 className="text-sm font-bold">ریز هزینه‌های دوره</h2>
        {period && period.items.length > 0 ? (
          <Table<ExpenseRow>
            size="small"
            rowKey="id"
            pagination={false}
            dataSource={period.items}
            columns={[
              { title: "دسته", key: "category", render: (_, row) => labelOf(row.category) },
              {
                title: "مبلغ",
                key: "amount_rial",
                render: (_, row) => `${fa(row.amount_rial)} ریال`,
              },
              { title: "تاریخ", dataIndex: "spent_on", key: "spent_on" },
              { title: "طرف‌حساب", dataIndex: "payee", key: "payee" },
              {
                title: "وضعیت",
                key: "status",
                render: (_, row) => (
                  <Tag color="green">{row.deleted_at ? "حذف‌شده" : "ثبت‌شده"}</Tag>
                ),
              },
              {
                title: "",
                key: "actions",
                render: (_, row) => (
                  <div className="flex gap-2">
                    <Button
                      size="small"
                      onClick={() => {
                        setEditing(row);
                        setEditAmount(row.amount_rial);
                        setEditReason("");
                      }}
                    >
                      اصلاح
                    </Button>
                    <Upload
                      accept="image/jpeg,image/png,image/webp"
                      showUploadList={false}
                      beforeUpload={(file) => {
                        void uploadReceipt(row.id, file);
                        return false;
                      }}
                    >
                      <Button size="small">فیش</Button>
                    </Upload>
                    <Button size="small" onClick={() => void openReceipt(row.id)}>
                      مشاهدهٔ فیش
                    </Button>
                    <Button size="small" danger onClick={() => setRemoving(row)}>
                      حذف
                    </Button>
                  </div>
                ),
              },
            ]}
          />
        ) : (
          <Empty description="هزینه‌ای در این دوره ثبت نشده است" />
        )}
      </div>

      {error && <Alert type="error" showIcon message={error} role="alert" />}

      <Modal
        title="اصلاح مبلغ هزینه"
        open={editing !== null}
        okText="ثبت اصلاح"
        cancelText="انصراف"
        confirmLoading={busy}
        onOk={() => void submitEdit()}
        onCancel={() => {
          setEditing(null);
          setEditReason("");
        }}
      >
        <p className="text-xs text-ink-dim">
          هر اصلاح در تاریخچه با دلیل ثبت می‌شود؛ مقدار قبلی حذف نمی‌شود.
        </p>
        <InputNumber<number>
          aria-label="مبلغ اصلاح‌شده"
          className="mt-3 block w-40"
          min={1000}
          step={1000}
          controls={false}
          value={editAmount}
          onChange={(value) => setEditAmount(value)}
        />
        <Input
          aria-label="دلیل اصلاح"
          className="mt-3"
          placeholder="دلیل اصلاح (اجباری)"
          value={editReason}
          onChange={(e) => setEditReason(e.target.value)}
        />
      </Modal>

      <Modal
        title="حذف هزینه"
        open={removing !== null}
        okText="حذف کن"
        cancelText="انصراف"
        okButtonProps={{ danger: true }}
        confirmLoading={busy}
        onOk={() => void submitRemove()}
        onCancel={() => {
          setRemoving(null);
          setRemoveReason("");
        }}
      >
        <p className="text-xs text-ink-dim">
          حذف نرم است: ردیف از جمع‌ها بیرون می‌رود ولی تاریخچه و ممیزی می‌ماند.
        </p>
        <Input
          aria-label="دلیل حذف"
          className="mt-3"
          placeholder="دلیل حذف (اجباری)"
          value={removeReason}
          onChange={(e) => setRemoveReason(e.target.value)}
        />
      </Modal>
    </section>
  );
}

import { motion } from "framer-motion";
import { PaymentPanel } from "../components/PaymentPanel";
import { CouponPanel } from "../components/CouponPanel";
import { LedgerPanel } from "../components/LedgerPanel";
import { ReceiptQueue } from "../components/ReceiptQueue";
import { PeriodReportPanel } from "../components/PeriodReportPanel";
import { useEffect, useState } from "react";
import {
  fetchCommission,
  fetchFinanceSummary,
  fetchPaymentsCsv,
  type CommissionResult,
  type FinanceSummary,
} from "../lib/api";
import { useMotionPreset } from "../lib/motion";
import { canSeePage, parseRole } from "../lib/roleNav";
import { fa } from "../lib/useApi";

const fmt = (n: number) => fa(n);

/**
 * مالی — خلاصه، کمیسیون مربی، خروجی CSV (M27/باز-۴).
 *
 * باگ M52-c1: این صفحه با `fetch` خام و **بدون هدر Authorization** صدا
 * می‌زد، پس هر سه دکمه در عمل ۴۰۱ می‌گرفتند — صفحهٔ مالی کاملاً مرده بود.
 * حالا از لایهٔ مشترک api استفاده می‌شود که bearer نشست را می‌گذارد؛ ۴۰۱
 * پیام ورود دوباره با OTP می‌دهد و ۴۰۳ جداگانه به‌عنوان نداشتن مجوز نمایش داده می‌شود.
 */
export function Finance() {
  // M60/R3: صفحهٔ مالی پیش‌تر برای هر نقشی رندر می‌شد و سه دکمه‌اش برای
  // reception/coach/member همه ۴۰۳ می‌گرفتند. حالا خودِ صفحه هم گیت می‌شود،
  // نه فقط منو — چون کاربر می‌تواند با URL/state مستقیم به صفحه برسد.
  // نقش ناشناخته (توکن غیر-JWT یا قدیمی) → گیت اعمال نمی‌شود و تصمیم با
  // سرور است. منطق: پنهان‌کردن صفحه بر پایهٔ حدس، کاربر را قفل می‌کند؛
  // سرور همچنان ۴۰۳ می‌دهد و پیامش نمایش داده می‌شود.
  const role = parseRole();
  const motionPreset = useMotionPreset();
  const [coachId, setCoachId] = useState("");
  const [rate, setRate] = useState("10");
  const [commission, setCommission] = useState<CommissionResult | null>(null);
  const [summary, setSummary] = useState<FinanceSummary | null>(null);
  const [error, setError] = useState("");
  const [busy, setBusy] = useState(false);

  const call = async (fn: () => Promise<void>) => {
    setError("");
    setBusy(true);
    try {
      await fn();
    } catch (e) {
      setError(e instanceof Error ? e.message : "خطای ناشناخته");
    } finally {
      setBusy(false);
    }
  };

  const fetchSummary = () =>
    call(async () => {
      setSummary(await fetchFinanceSummary());
    });

  // خلاصه هنگام باز شدن صفحه بارگذاری می‌شود — صفحهٔ مالی نباید تا کلیک
  // کاربر خالی بماند و «خراب» به نظر برسد.
  useEffect(() => {
    void fetchSummary();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const calculateCommission = () =>
    call(async () => {
      if (!coachId.trim()) throw new Error("شناسهٔ مربی را وارد کنید");
      const id = Number(coachId);
      if (!Number.isFinite(id) || id < 1) throw new Error("شناسهٔ مربی باید عدد مثبت باشد");
      const pct = Number(rate);
      if (!Number.isFinite(pct) || pct < 0 || pct > 100) {
        throw new Error("درصد کمیسیون باید بین ۰ تا ۱۰۰ باشد");
      }
      setCommission(await fetchCommission(id, pct / 100));
    });

  const downloadCsv = () =>
    call(async () => {
      const blob = await fetchPaymentsCsv();
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = "payments-export.csv";
      a.click();
      URL.revokeObjectURL(url);
    });

  if (role && !canSeePage("finance", role)) {
    return (
      <div className="glass-card p-5 text-sm text-ink-dim" role="alert">
        گزارش مالی برای نقش شما مجاز نیست. سرور هم این را رد می‌کند (۴۰۳) — این پیام
        فقط توضیح می‌دهد چرا صفحه خالی است.
      </div>
    );
  }

  return (
    <motion.div {...motionPreset.rise} className="space-y-4">
      <div className="glass-card space-y-4 p-5">
        <h2 className="text-sm font-bold">گزارش مالی</h2>
        <div className="flex items-center gap-3">
          <button onClick={fetchSummary} disabled={busy} className="focus-ring rounded-xl bg-primary px-4 py-2 text-sm text-white transition-transform hover:scale-[1.02] active:scale-95">
            خلاصهٔ مالی
          </button>
          <button onClick={downloadCsv} disabled={busy} className="focus-ring rounded-xl border border-primary/40 px-4 py-2 text-sm text-primary-light transition-colors hover:bg-primary/10">
            دانلود CSV حسابداری
          </button>
        </div>
        {summary && (
          <motion.div initial={{ opacity: 0, y: 6 }} animate={{ opacity: 1, y: 0 }} className="grid grid-cols-3 gap-3 text-center">
            <div className="rounded-xl bg-primary/10 p-3">
              <p className="text-xs text-ink-dim">پرداخت‌شده (ریال)</p>
              <p className="text-lg font-bold">{fmt(summary.total_paid_rial)}</p>
            </div>
            <div className="rounded-xl bg-primary/10 p-3">
              <p className="text-xs text-ink-dim">در انتظار (ریال)</p>
              <p className="text-lg font-bold">{fmt(summary.total_pending_rial)}</p>
            </div>
            <div className="rounded-xl bg-primary/10 p-3">
              <p className="text-xs text-ink-dim">تعداد پرداخت موفق</p>
              <p className="text-lg font-bold">{fmt(summary.paid_count)}</p>
            </div>
          </motion.div>
        )}
      </div>

      <PaymentPanel />

      <CouponPanel />

      <ReceiptQueue />

      <LedgerPanel />

      <div className="glass-card space-y-4 p-5">
        <h2 className="text-sm font-bold">سود و زیان دوره‌ای (QF-10)</h2>
        <PeriodReportPanel />
      </div>

      <div className="glass-card space-y-4 p-5">
        <h2 className="text-sm font-bold">کمیسیون مربی</h2>
        <div className="flex flex-wrap items-center gap-3">
          <input
            value={coachId}
            onChange={(e) => setCoachId(e.target.value)}
            placeholder="شناسهٔ مربی"
            inputMode="numeric"
            className="focus-ring w-36 rounded-xl border border-primary/30 bg-transparent px-3 py-2 text-sm"
          />
          <input
            value={rate}
            onChange={(e) => setRate(e.target.value)}
            placeholder="درصد"
            inputMode="decimal"
            className="focus-ring w-24 rounded-xl border border-primary/30 bg-transparent px-3 py-2 text-sm"
          />
          <button onClick={calculateCommission} disabled={busy} className="focus-ring rounded-xl bg-primary px-4 py-2 text-sm text-white transition-transform hover:scale-[1.02] active:scale-95">
            محاسبه
          </button>
        </div>
        {commission && (
          <motion.div initial={{ opacity: 0, y: 6 }} animate={{ opacity: 1, y: 0 }} className="rounded-xl bg-primary/10 p-4 text-sm leading-7">
            <p>مربی: <b>{commission.coach_name}</b> (#{commission.coach_id})</p>
            <p>پرداخت‌های منتسب: <b>{fmt(commission.attributed_payments_rial)}</b> ریال</p>
            <p>کمیسیون {fmt(commission.rate * 100)}٪: <b className="text-primary-light">{fmt(commission.commission_rial)}</b> ریال</p>
          </motion.div>
        )}
      </div>

      {error && (
        <motion.p initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="rounded-xl border border-red-500/40 bg-red-500/10 px-4 py-2 text-sm text-red-400">
          ⚠ {error}
        </motion.p>
      )}
    </motion.div>
  );
}

import { useState } from "react";
import { AnimatePresence, motion } from "framer-motion";
import { useMotionPreset } from "../lib/motion";
import { MemberTable } from "../components/MemberTable";
import { generateProgram, fetchAssessmentHistory, fetchAssessmentMatrix, fetchMembersSummary } from "../lib/api";
import { fa, useApi } from "../lib/useApi";
import { useAppStore } from "../stores/appStore";

const domains = [
  "قلبی-عروقی", "عضلانی-اسکلتی", "کنترل وزن", "انعطاف‌پذیری", "قدرت", "استقامت",
  "تعادل", "هماهنگی", "سرعت", "چابکی", "سلامت مفاصل", "الگوی خواب", "سطح استرس", "تغذیه",
];

/** اعضا + پنل جزئیات با ورود/خروج انیمیشنی (AnimatePresence). */
const genderTabs = [
  { key: "all" as const, label: "همه" },
  { key: "male" as const, label: "آقایان" },
  { key: "female" as const, label: "بانوان" },
];

export function Members() {
  const motionPreset = useMotionPreset();
  const { selectedMemberId, selectMember, genderFilter, setGenderFilter, setPage } =
    useAppStore();
  const [busy, setBusy] = useState(false);
  const [genMsg, setGenMsg] = useState<string | null>(null);
  const [genError, setGenError] = useState<string | null>(null);

  async function buildProgram() {
    if (!member) return;
    setBusy(true);
    setGenError(null);
    setGenMsg(null);
    try {
      const p = await generateProgram(member.member_id, { goal: "hypertrophy" });
      setGenMsg(
        `برنامهٔ #${p.id} به‌صورت draft ساخته شد (موتور ${p.engine_version}) — برای تأیید به صفحهٔ برنامه‌ها بروید.`,
      );
    } catch (e) {
      setGenError((e as Error).message);
    } finally {
      setBusy(false);
    }
  }
  // داده از API می‌آید (MemberTable خودش می‌خواند)؛ اینجا فقط برای پنل جزئیات
  const { data } = useApi((s) => fetchMembersSummary(undefined, s), []);
  const member = data?.items.find((m) => m.member_id === selectedMemberId) ?? null;

  const history = useApi(
    (s) => (member ? fetchAssessmentHistory(member.member_id, undefined, s) : Promise.resolve([])),
    [member?.member_id],
  );
  const latestAssessment = history.data?.[0] ?? null;
  const matrixState = useApi(
    (s) =>
      latestAssessment
        ? fetchAssessmentMatrix(latestAssessment.assessment_id, undefined, s)
        : Promise.resolve(null),
    [latestAssessment?.assessment_id],
  );
  const matrix = matrixState.data;
  const historyLoading = history.loading || matrixState.loading;
  const matrixError = matrixState.error ?? "ماتریس ارزیابی دریافت نشد";

  return (
    <div className="grid grid-cols-1 gap-6 xl:grid-cols-3">
      <div className="xl:col-span-2">
        <div className="mb-4 flex items-center gap-2">
          {genderTabs.map((t) => (
            <button
              key={t.key}
              onClick={() => setGenderFilter(t.key)}
              className={`rounded-full px-4 py-1.5 text-xs font-semibold transition-colors ${
                genderFilter === t.key
                  ? "bg-primary text-white"
                  : "bg-surface/70 text-ink-dim hover:text-ink"
              }`}
            >
              {t.label}
            </button>
          ))}
          <span className="mr-auto text-[11px] text-ink-dim">تفکیک جنسیت (M41) — نمای کامل ادمین</span>
        </div>
        <MemberTable onSelect={(id) => selectMember(id)} />
      </div>

      <AnimatePresence mode="wait">
        {member ? (
          <motion.div
            key={member.member_id}
            {...motionPreset.slide}
            exit={{ opacity: 0, x: -20 }}
            transition={{ type: "spring", stiffness: 260, damping: 24 }}
            className="glass-card p-5"
          >
            <div className="flex items-center gap-3">
              <div
                className="flex h-14 w-14 items-center justify-center rounded-2xl text-lg font-bold text-white"
                style={{
                  background: `linear-gradient(135deg, hsl(${(member.member_id * 47) % 360} 60% 38%), hsl(${(member.member_id * 47) % 360} 55% 22%))`,
                }}
              >
                {(member.full_name || "?").slice(0, 1)}
              </div>
              <div>
                <h2 className="text-lg font-bold">{member.full_name || "بدون نام"}</h2>
                <p className="text-xs text-ink-dim">
                  {member.phone || "—"} · هدف: {member.goal} ·{" "}
                  <span className={member.gender === "female" ? "text-pink-400" : "text-sky-400"}>
                    {member.gender === "female" ? "بانو" : "آقا"}
                  </span>
                </p>
              </div>
            </div>

            <div className="mt-5 grid grid-cols-2 gap-3">
              <div className="rounded-xl bg-surface/70 p-3 text-center">
                <p className="text-2xl font-bold text-primary-light">
                  {member.days_left == null ? "—" : fa(member.days_left)}
                </p>
                <p className="text-xs text-ink-dim">روز باقی‌مانده</p>
              </div>
              <div className="rounded-xl bg-surface/70 p-3 text-center">
                <p className="text-2xl font-bold text-accent-soft">
                  {member.plan_name ?? "—"}
                </p>
                <p className="text-xs text-ink-dim">پلن فعلی</p>
              </div>
            </div>

            <h4 className="mt-5 text-sm font-semibold">
              ارزیابی ۱۴ محور
              {matrix && (
                <span className="mr-2 text-[11px] font-normal text-ink-dim">
                  {matrix.status} · {matrix.rule_versions?.score}
                </span>
              )}
            </h4>
            {historyLoading ? (
              <p className="mt-3 text-xs text-ink-dim">در حال دریافت…</p>
            ) : !latestAssessment ? (
              <p className="mt-3 rounded-lg bg-surface/50 p-3 text-xs text-ink-dim">
                این عضو هیچ ارزیابی ثبت‌شده‌ای ندارد — نمره‌ای نمایش داده نمی‌شود.
              </p>
            ) : matrix ? (
              <div className="mt-3 space-y-2">
                {matrix.axes.map((axis, i) => (
                  <div key={axis.axis} className="flex items-center gap-2">
                    <span className="w-28 shrink-0 text-[11px] text-ink-dim">{axis.name_fa}</span>
                    <div className="h-1.5 flex-1 overflow-hidden rounded-full bg-surface">
                      {axis.score == null ? (
                        <div className="h-full w-full bg-[repeating-linear-gradient(45deg,rgba(156,163,175,0.25)_0_4px,transparent_4px_8px)]" />
                      ) : (
                        <motion.div
                          initial={motionPreset.reduced ? false : { width: 0 }}
                          animate={{ width: `${axis.score}%` }}
                          transition={
                            motionPreset.reduced
                              ? { duration: 0 }
                              : { delay: motionPreset.stagger(i), duration: 0.5 }
                          }
                          className="h-full rounded-full bg-gradient-to-l from-primary to-primary-light"
                        />
                      )}
                    </div>
                    <span className="w-10 text-left text-[11px] text-ink-dim">
                      {axis.score == null ? "نامعلوم" : fa(axis.score)}
                    </span>
                  </div>
                ))}
              </div>
            ) : (
              <p className="mt-3 text-xs text-danger">{matrixError}</p>
            )}

            <div className="mt-5 space-y-2">
              <div className="flex gap-2">
                <button
                  onClick={() => void buildProgram()}
                  disabled={busy || !member}
                  className="btn-primary flex-1 disabled:opacity-50"
                >
                  {busy ? "در حال ساخت…" : "ساخت برنامه از موتور قواعد"}
                </button>
                <button
                  onClick={() => setPage("programs")}
                  className="btn-ghost flex-1"
                  title="ثبت ارزیابی در صفحهٔ برنامه‌ها و ارزیابی انجام می‌شود"
                >
                  دیدن برنامه‌ها
                </button>
              </div>
              {genMsg && (
                <p className="rounded-lg bg-emerald-500/10 px-3 py-2 text-xs text-emerald-300">
                  {genMsg}
                </p>
              )}
              {genError && (
                <p className="rounded-lg bg-rose-500/10 px-3 py-2 text-xs text-rose-300" role="alert">
                  {genError}
                </p>
              )}
            </div>
          </motion.div>
        ) : (
          <motion.div
            key="empty"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="glass-card flex flex-col items-center justify-center p-10 text-center"
          >
            <div className="mb-3 flex h-16 w-16 items-center justify-center rounded-2xl bg-primary/10 text-2xl">👤</div>
            <p className="text-sm text-ink-dim">یک عضو را از فهرست انتخاب کنید</p>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}

